import { BENCH_CATALOG, BENCH_WIDTH, BENCH_HEIGHT, paintWidget } from './bench-widgets.js?v=glyph-2';
import { normalizeWidget, normalizeBenchState, saveBenchState, loadBenchState, exportBenchState, parseBenchFile } from './bench-store.js?v=glyph-2';
import { mountBenchConsole } from './bench-console.js?v=glyph-2';
import { createBenchRenderer } from './bench-renderer.js?v=glyph-2';

const loaded=loadBenchState();let state=loaded.state,renderer=null,consoleView=null,saveTimer=0,category='All',dirty=false,saveQuiet=false,inspectorId=null;
const storageKey='phosphor-component-workbench-v1';
const cards=new Map(),grid=document.querySelector('#component-grid'),saveStatus=document.querySelector('#bench-save-status'),errorBox=document.querySelector('#bench-error');
const numericIds=new Set(['dial','wheel','bar','slider','percentage','stepper','level']);
const descriptions={dial:'Drag vertically, scroll, or use arrow keys.',wheel:'Drag or scroll to turn. Arrow keys make one step.',bar:'Click or drag the bar to set progress.',slider:'Drag the slider or use arrow keys.',percentage:'Adjust the value to test the percentage readout.',indicators:'Toggle each status lamp independently.',search:'Type to search the four display layers.',buttons:'Latch each button on or off.',toggle:'Click to switch the circuit on or off.',stepper:'Use minus and plus, or enter a value.',level:'Adjust the signal to test the level meter.',segments:'Choose one of three operating modes.'};
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function report(message,error=false){saveStatus.textContent=message;saveStatus.classList.toggle('error',error);}
function showError(message){errorBox.hidden=!message;errorBox.textContent=message||'';}
function persist({quiet=false}={}){clearTimeout(saveTimer);saveTimer=0;const result=saveBenchState(state);dirty=!result.ok;if(!quiet||!result.ok)report(result.ok?'All changes saved on this device':result.error,!result.ok);for(const card of cards.values()){card.noteStatus.textContent=result.ok?(state.widgets[card.id].notes?'Note saved':'No note yet'):'Session only';}document.querySelector('#selected-note-status').textContent=result.ok?'Note saved on this device':'Session only';filterCards({preserveFocus:true});return result.ok;}
function scheduleSave(id,{quiet=false}={}){saveQuiet=dirty?saveQuiet&&quiet:quiet;dirty=true;clearTimeout(saveTimer);if(!saveQuiet){report('Saving changes…');document.querySelector('#selected-note-status').textContent='Saving…';if(id)cards.get(id).noteStatus.textContent='Saving…';}saveTimer=setTimeout(()=>persist({quiet:saveQuiet}),350);}
function paint(id){const card=cards.get(id);paintWidget(card.context,id,state.widgets[id]);renderer?.invalidate(id);if(id===state.screens.selected)consoleView?.refresh();}
function updateWidget(id,patch){const card=cards.get(id);state.widgets[id]=normalizeWidget({...state.widgets[id],...patch},card.meta.defaults);syncCard(id);paint(id);syncConsoleInspector();scheduleSave(id);}
function syncConsoleInspector(){
  const id=state.screens.selected,c=state.widgets[id],meta=BENCH_CATALOG.find(item=>item.id===id),selectionChanged=inspectorId!==id;inspectorId=id;
  document.querySelector('#selected-component-title').textContent=meta.name;
  for(const [field,selector] of [['label','#selected-label'],['color','#selected-color'],['mark','#selected-mark'],['notes','#selected-note']]){
    const input=document.querySelector(selector);if(selectionChanged||document.activeElement!==input)input.value=c[field];
  }
  const value=document.querySelector('#selected-value');value.min=c.min;value.max=c.max;value.step=c.step;value.value=c.value;value.disabled=c.disabled;
  document.querySelector('#selected-value-field').hidden=!numericIds.has(id);
  document.querySelector('#selected-value-output').textContent=c.value+(c.unit?' '+c.unit:'');
  for(const card of cards.values()){
    card.article.classList.toggle('is-selected',card.id===id);
    const button=card.article.querySelector('.preview-component');button.setAttribute('aria-pressed',String(card.id===id));button.textContent=card.id===id?'In console':'Test';
  }
  for(const button of document.querySelectorAll('[data-all-mark]'))button.setAttribute('aria-pressed',String(BENCH_CATALOG.every(item=>state.widgets[item.id].mark===button.dataset.allMark)));
}
function changeScreens(patch,options={}){state=normalizeBenchState({...state,screens:{...state.screens,...patch}});syncConsoleInspector();consoleView?.refresh();scheduleSave(undefined,options);}
function editWidget(id){
  if(state.screens.selected!==id)changeScreens({selected:id});
  category='All';document.querySelector('#component-filter').value='';document.querySelectorAll('[data-category]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.category==='All')));filterCards();
  const card=cards.get(id);card.article.querySelector('details').open=true;card.article.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
}
function filterCards({preserveFocus=false}={}){const query=document.querySelector('#component-filter').value.trim().toLowerCase();const focusedEditor=preserveFocus&&document.activeElement?.matches('input,textarea,select')?document.activeElement:null;let count=0;for(const meta of BENCH_CATALOG){const c=state.widgets[meta.id],article=cards.get(meta.id).article;const matchesCategory=category==='All'||category===meta.category||category==='Notes'&&Boolean(c.notes.trim());const haystack=[meta.name,c.label,meta.description,c.notes].join(' ').toLowerCase();const visible=matchesCategory&&(!query||haystack.includes(query))||Boolean(focusedEditor&&article.contains(focusedEditor));article.hidden=!visible;if(visible)count++;}document.querySelector('#visible-count').textContent=count+' component'+(count===1?'':'s');document.querySelector('#empty-state').hidden=count!==0;renderer?.draw();}
function searchResults(query){const matches=['PHOSPHOR','GRID','FILAMENT','GLASS'].filter(name=>name.includes(query.trim().toUpperCase()));return matches.length?matches.length+' matching display layer'+(matches.length===1?'':'s')+': '+matches.join(', '):'No matching display layers';}
function syncCard(id){const card=cards.get(id),c=state.widgets[id];card.article.style.setProperty('--component-color',c.color);card.article.classList.toggle('is-disabled',c.disabled);card.title.textContent=c.label||card.meta.name;card.scale.style.transform='scale('+c.size/100+')';card.noteTag.classList.toggle('has-note',Boolean(c.notes.trim()));
  for(const input of card.article.querySelectorAll('[data-field]')){const field=input.dataset.field;if(input.type==='checkbox')input.checked=c[field];else if(document.activeElement!==input)input.value=c[field];}
  card.article.querySelector('[data-size-output]').textContent=c.size+'%';
  for(const input of card.article.querySelectorAll('[data-test-value]')){input.min=c.min;input.max=c.max;input.step=c.step;input.value=c.value;input.disabled=c.disabled;}
  for(const hit of card.hits){hit.disabled=c.disabled;if(hit.getAttribute('role')==='slider'){hit.setAttribute('aria-valuemin',c.min);hit.setAttribute('aria-valuemax',c.max);hit.setAttribute('aria-valuenow',c.value);hit.setAttribute('aria-valuetext',c.value+' '+c.unit);hit.setAttribute('aria-disabled',String(c.disabled));hit.tabIndex=c.disabled?-1:0;}if(hit.dataset.active!==undefined)hit.setAttribute('aria-pressed',String(c.active[Number(hit.dataset.active)]));if(hit.dataset.option!==undefined)hit.setAttribute('aria-pressed',String(c.option===Number(hit.dataset.option)));if(hit.type==='search'&&document.activeElement!==hit)hit.value=c.query;}
  if(card.liveStatus){card.liveStatus.textContent=id==='search'?searchResults(c.query):id==='toggle'?(c.active[0]?'Circuit enabled':'Circuit disabled'):id==='segments'?['Automatic mode','Manual mode','Test mode'][c.option]:c.active.map((on,i)=>(id==='indicators'?['READY','WARN','FAULT']:['ARM','HOLD','RESET'])[i]+': '+(on?'ON':'OFF')).join(' · ');}
}
function hit(card,tag,label,x,y,width,height){const el=document.createElement(tag);el.className='widget-hit';if(tag==='button')el.type='button';el.setAttribute('aria-label',label);Object.assign(el.style,{left:x+'px',top:y+'px',width:width+'px',height:height+'px'});card.scale.append(el);card.hits.push(el);return el;}
function changeValue(id,value){if(!state.widgets[id].disabled)updateWidget(id,{value});}
function numericHit(card,seek=false){const el=hit(card,'div',card.meta.name,seek?24:50,seek?75:35,seek?272:220,seek?65:135);el.setAttribute('role','slider');el.tabIndex=0;if(seek)el.classList.add('widget-seek');let drag=null;
  el.addEventListener('keydown',event=>{const c=state.widgets[card.id];if(c.disabled)return;let value=c.value;const delta=(event.shiftKey?10:1)*c.step;if(['ArrowUp','ArrowRight'].includes(event.key))value+=delta;else if(['ArrowDown','ArrowLeft'].includes(event.key))value-=delta;else if(event.key==='Home')value=c.min;else if(event.key==='End')value=c.max;else if(event.key==='PageUp')value+=(c.max-c.min)/10;else if(event.key==='PageDown')value-=(c.max-c.min)/10;else return;event.preventDefault();changeValue(card.id,value);});
  function seekTo(event){const rect=el.getBoundingClientRect(),c=state.widgets[card.id];changeValue(card.id,c.min+Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width))*(c.max-c.min));}
  el.addEventListener('pointerdown',event=>{if(state.widgets[card.id].disabled||!event.isPrimary)return;event.preventDefault();el.focus();el.setPointerCapture(event.pointerId);drag={y:event.clientY,value:state.widgets[card.id].value};if(seek)seekTo(event);});
  el.addEventListener('pointermove',event=>{if(!drag)return;if(seek)seekTo(event);else{const c=state.widgets[card.id];changeValue(card.id,drag.value+(drag.y-event.clientY)*(c.max-c.min)/160);}});
  const end=event=>{drag=null;if(el.hasPointerCapture(event.pointerId))el.releasePointerCapture(event.pointerId);};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('lostpointercapture',()=>drag=null);
  if(!seek)el.addEventListener('wheel',event=>{if(state.widgets[card.id].disabled)return;event.preventDefault();const c=state.widgets[card.id];changeValue(card.id,c.value+(event.deltaY<0?c.step:-c.step));},{passive:false});
}
function addInteractions(card){const id=card.id,name=card.meta.name;
  if(['dial','wheel'].includes(id))numericHit(card);
  if(['bar','slider'].includes(id))numericHit(card,true);
  if(['buttons','indicators','segments'].includes(id)){const labels=id==='buttons'?['ARM','HOLD','RESET']:id==='indicators'?['READY','WARN','FAULT']:['AUTO','MANUAL','TEST'];labels.forEach((label,i)=>{const el=hit(card,'button',name+' '+label,20+i*95,id==='indicators'?60:80,90,id==='indicators'?90:44);el.dataset[id==='segments'?'option':'active']=i;el.addEventListener('click',()=>{if(id==='segments')updateWidget(id,{option:i});else{const active=[...state.widgets[id].active];active[i]=!active[i];updateWidget(id,{active});}});});}
  if(id==='toggle'){const el=hit(card,'button','Toggle circuit',110,75,100,50);el.dataset.active=0;el.addEventListener('click',()=>{const active=[...state.widgets[id].active];active[0]=!active[0];updateWidget(id,{active});});}
  if(id==='stepper'){for(const [action,x,sign]of[['Decrease',25,-1],['Increase',240,1]]){const el=hit(card,'button',action+' stepper',x,80,55,45);el.addEventListener('click',()=>{const c=state.widgets[id];changeValue(id,c.value+sign*c.step);});}}
  if(id==='search'){const el=hit(card,'input','Search display layers',20,60,280,38);el.type='search';el.maxLength=80;el.autocomplete='off';el.spellcheck=false;el.addEventListener('input',()=>updateWidget(id,{query:el.value}));el.addEventListener('keydown',event=>{if(event.key==='Escape'){el.value='';updateWidget(id,{query:''});}});}
}
function makeCard(meta,index){const c=state.widgets[meta.id],name=escapeHTML(meta.name),id=meta.id;const article=document.createElement('article');article.className='component-card';article.id='component-'+id;article.dataset.component=id;
  article.innerHTML=`<header><span class="component-index">${String(index+1).padStart(2,'0')}</span><div class="component-heading"><h2></h2><p>${escapeHTML(meta.category)} / ${name}</p></div><button class="preview-component" type="button" aria-pressed="false" aria-label="Test ${name} in console">Test</button><button class="export-widget" type="button" aria-label="Export ${name} PNG">PNG</button></header><div class="component-body"><div class="preview-column"><div class="widget-preview" aria-label="${name} preview"><div class="widget-hit-map"><div class="widget-hit-scale"></div></div></div><p class="widget-hint">${escapeHTML(descriptions[id])}</p>${numericIds.has(id)?`<div class="test-value"><input data-test-value type="range" aria-label="${name} test value"><input data-test-value type="number" aria-label="${name} numeric value"></div>`:'<div class="preview-status" aria-live="polite"></div>'}</div><aside class="notes-column"><div class="notes-heading"><label for="note-${id}">EDIT NOTES</label><span class="note-tag" aria-hidden="true"></span></div><textarea id="note-${id}" data-field="notes" maxlength="4000" aria-label="${name} edit notes" placeholder="What would you change?\nSize, motion, labels, behavior…"></textarea><div class="note-bottom"><small class="note-status">${c.notes?'Note saved':'No note yet'}</small><button type="button" class="save-note" aria-label="Save ${name} note">Save note</button></div></aside></div><details class="component-modifiers"><summary>Modify component <span>Label, color, size & behavior</span></summary><div class="modifier-fields"><label class="wide">Display label<input type="text" maxlength="40" data-field="label" aria-label="${name} display label"></label><label class="color-field">Color<input type="color" data-field="color" aria-label="${name} color"></label><label class="scale-field"><span>Size <output data-size-output>100%</output></span><input type="range" min="80" max="120" step="1" data-field="size" aria-label="${name} size"></label><label>Fill marks<select data-field="mark" aria-label="${name} fill marks"><option value="dots">· Dots</option><option value="hashes"># Hashes</option><option value="blocks">■ Blocks</option><option value="lines">≡ Lines</option></select></label><label>Style<select data-field="variant" aria-label="${name} style"><option value="outline">Outline</option><option value="solid">Solid</option><option value="minimal">Minimal</option></select></label>${numericIds.has(id)?`<label>Minimum<input type="number" min="-9999" max="9999" step="any" data-field="min" aria-label="${name} minimum"></label><label>Maximum<input type="number" min="-9999" max="9999" step="any" data-field="max" aria-label="${name} maximum"></label><label>Step<input type="number" min="0.01" max="999" step="any" data-field="step" aria-label="${name} step"></label><label>Unit<input type="text" maxlength="10" data-field="unit" aria-label="${name} unit"></label>`:''}<label class="check-field"><input type="checkbox" data-field="disabled" aria-label="Disable ${name}">Disabled state</label><button type="button" class="reset-control" aria-label="Reset ${name} control">Reset control</button></div></details>`;
  grid.append(article);const source=document.createElement('canvas');source.width=BENCH_WIDTH;source.height=BENCH_HEIGHT;
  const card={id,meta,article,source,context:source.getContext('2d'),element:article.querySelector('.widget-preview'),map:article.querySelector('.widget-hit-map'),scale:article.querySelector('.widget-hit-scale'),title:article.querySelector('h2'),noteTag:article.querySelector('.note-tag'),noteStatus:article.querySelector('.note-status'),liveStatus:article.querySelector('.preview-status'),hits:[]};cards.set(id,card);addInteractions(card);
  for(const input of article.querySelectorAll('[data-field]')){
    const commit=()=>{const field=input.dataset.field;if(input.type==='number'&&(!input.value||!Number.isFinite(Number(input.value)))){input.value=state.widgets[id][field];return;}
      const value=input.type==='checkbox'?input.checked:['number','range'].includes(input.type)?Number(input.value):input.value;
      if(state.widgets[id][field]!==value)updateWidget(id,{[field]:value});
      if(input.type==='number')input.value=state.widgets[id][field];
    };
    input.addEventListener(input.type==='number'?'change':'input',commit);
    if(input.type==='number'){input.addEventListener('blur',commit);input.addEventListener('keydown',event=>{if(event.key==='Enter')commit();});}
  }
  for(const input of article.querySelectorAll('[data-test-value]')){
    const commit=()=>{if(input.value!==''&&Number.isFinite(Number(input.value)))changeValue(id,Number(input.value));else input.value=state.widgets[id].value;};
    input.addEventListener(input.type==='number'?'change':'input',commit);
    if(input.type==='number'){input.addEventListener('blur',commit);input.addEventListener('keydown',event=>{if(event.key==='Enter')commit();});}
  }
  article.querySelector('.preview-component').addEventListener('click',()=>{changeScreens({selected:id});document.querySelector('#combined-title').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
  article.querySelector('.save-note').addEventListener('click',()=>{persist();filterCards();});article.querySelector('.reset-control').addEventListener('click',()=>{updateWidget(id,{...meta.defaults,notes:state.widgets[id].notes});syncCard(id);});
  article.querySelector('.export-widget').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{if(!renderer)throw new Error('GPU export is unavailable in the fallback preview.');const blob=await renderer.exportPNG(id);download(blob,'phosphor-'+id+'.png');report(name+' PNG exported');}catch(error){report(error.message,true);}finally{button.disabled=false;}});
  article.querySelector('details').addEventListener('toggle',()=>renderer?.draw());syncCard(id);paint(id);return card;
}
BENCH_CATALOG.forEach(makeCard);
grid.addEventListener('focusout',()=>queueMicrotask(()=>filterCards({preserveFocus:true})));
const previewResize=new ResizeObserver(entries=>{for(const entry of entries){const card=[...cards.values()].find(c=>c.element===entry.target);if(card)card.map.style.transform='scale('+(card.element.clientWidth/BENCH_WIDTH)+')';}renderer?.draw();});for(const card of cards.values())previewResize.observe(card.element);
const consoleHost=document.querySelector('#combined-display');
consoleHost.addEventListener('bench-console-paint',()=>renderer?.invalidate('console'));
consoleView=mountBenchConsole(consoleHost,{getState:()=>state,onScreensChange:changeScreens,onWidgetChange:updateWidget,onEditWidget:editWidget});
function fallback(){consoleView.source.className='fallback-preview';consoleView.source.setAttribute('aria-hidden','true');consoleHost.prepend(consoleView.source);for(const card of cards.values()){card.source.className='fallback-preview';card.source.setAttribute('aria-hidden','true');card.element.prepend(card.source);}}
try{renderer=createBenchRenderer(document.querySelector('#bench-gl'),[{id:'console',element:consoleHost,source:consoleView.source},...[...cards.values()].map(c=>({id:c.id,element:c.element,source:c.source}))],state.optics);}catch(error){fallback();showError('WebGL is unavailable. Basic previews still work; GPU effects and PNG export need WebGL 2.');console.error(error);}
document.querySelector('#bench-gl').addEventListener('bench-renderer-state',event=>{showError(event.detail.available?'':'The graphics connection was interrupted. Waiting for the previews to recover…');});
function syncOptics(){for(const input of document.querySelectorAll('[data-optics]')){input.value=state.optics[input.dataset.optics];document.querySelector('[data-optics-output="'+input.dataset.optics+'"]').textContent=input.value+'%';}renderer?.setOptics(state.optics);}
for(const input of document.querySelectorAll('[data-optics]'))input.addEventListener('input',()=>{state=normalizeBenchState({...state,optics:{...state.optics,[input.dataset.optics]:Number(input.value)}});syncOptics();scheduleSave();});
syncOptics();syncConsoleInspector();
for(const [field,selector] of [['label','#selected-label'],['color','#selected-color'],['mark','#selected-mark'],['notes','#selected-note']])document.querySelector(selector).addEventListener('input',event=>updateWidget(state.screens.selected,{[field]:event.target.value}));
document.querySelector('#selected-value').addEventListener('input',event=>changeValue(state.screens.selected,Number(event.target.value)));
document.querySelector('#save-selected-note').addEventListener('click',persist);
document.querySelector('#edit-selected-component').addEventListener('click',()=>editWidget(state.screens.selected));
for(const button of document.querySelectorAll('[data-all-mark]'))button.addEventListener('click',()=>{
  for(const meta of BENCH_CATALOG){state.widgets[meta.id]=normalizeWidget({...state.widgets[meta.id],mark:button.dataset.allMark},meta.defaults);syncCard(meta.id);paint(meta.id);}
  syncConsoleInspector();scheduleSave();
});
document.querySelector('#component-filter').addEventListener('input',filterCards);for(const button of document.querySelectorAll('[data-category]'))button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filterCards();});
document.querySelector('#clear-filters').addEventListener('click',()=>{document.querySelector('#component-filter').value='';category='All';document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category==='All')));filterCards();});
document.querySelector('#save-bench').addEventListener('click',persist);
function download(blob,name){const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.querySelector('#export-bench').addEventListener('click',()=>{download(new Blob([exportBenchState(state)],{type:'application/json'}),'phosphor-workbench.json');report('Workbench and all edit notes exported');});
const fileInput=document.querySelector('#bench-file');document.querySelector('#import-bench').addEventListener('click',()=>fileInput.click());fileInput.addEventListener('change',async()=>{const file=fileInput.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Choose a workbench file smaller than 1 MB.');const imported=parseBenchFile(await file.text());state=imported;dirty=true;for(const card of cards.values()){syncCard(card.id);paint(card.id);}syncOptics();syncConsoleInspector();consoleView.refresh();filterCards();const saved=persist();if(saved)report('Imported all components and edit notes');}catch(error){report(error.message,true);}finally{fileInput.value='';}});
window.addEventListener('storage',event=>{if(event.key!==storageKey&&event.key!==null)return;if(dirty){report('Another tab changed the workbench. Your pending edits are kept.');return;}const latest=loadBenchState();if(latest.warning){report(latest.warning,true);return;}state=latest.state;for(const card of cards.values()){syncCard(card.id);paint(card.id);card.noteStatus.textContent=state.widgets[card.id].notes?'Note saved':'No note yet';}syncOptics();syncConsoleInspector();consoleView.refresh();filterCards({preserveFocus:true});report('Workbench updated from another tab');});
window.addEventListener('pagehide',()=>{if(dirty)persist();});
if(loaded.warning)report(loaded.warning,true);
